(208050, 11845, 2716, '<td valign="top">Superb silouette.  I really love the colour of the sky.</td>', 'Superb silouette.  I really love the colour of the sky.', '2003-02-04 20:02:06.000000', NULL, 1),
(208051, 12027, 2716, '<td valign="top">What a beautifull dog.  Neat use of negative space.  Good job.</td>', 'What a beautifull dog.  Neat use of negative space.  Good job.', '2003-02-04 20:02:40.000000', NULL, 1),
(208052, 11892, 2553, '<td valign="top">Wonderful shot, the lighting is lovely.  Only gripe- wish the cat was looking at the camera!  Nevertheless, it''s beautiful.</td>', 'Wonderful shot, the lighting is lovely.  Only gripe- wish the cat was looking at the camera!  Nevertheless, it''s beautiful.', '2003-02-04 20:02:41.000000', NULL, 1),
