INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(208954, 12002, 4815, '<td valign="top">An elegant well composed photo. The white petal exposure and color are perfect. The border is well done. I like the reflected flowers and the feeling of a suspended in mid air vase. The gentle lightingon the vase is flattering to the delicate tones. Good job.</td>', 'An elegant well composed photo. The white petal exposure and color are perfect. The border is well done. I like the reflected flowers and the feeling of a suspended in mid air vase. The gentle lightingon the vase is flattering to the delicate tones. Good job.', '2003-02-05 18:17:27.000000', NULL, 1),
(208955, 11969, 4494, '<td valign="top">Nice exageration of the colors.  Not really a cliche is it?  I like it overall.</td>', 'Nice exageration of the colors.  Not really a cliche is it?  I like it overall.', '2003-02-05 18:18:11.000000', NULL, 1),
(208957, 12046, 4815, '<td valign="top">Great DOF for this shot. Nice sharply focused whiskers and fur. The alluring green eye and orangish nose are lovely accents to the earth tones. Personal wee quibble would be a desire to have a touch more space around the nose tip. Purr-fect exposure. Great photo.</td>', 'Great DOF for this shot. Nice sharply focused whiskers and fur. The alluring green eye and orangish nose are lovely accents to the earth tones. Personal wee quibble would be a desire to have a touch more space around the nose tip. Purr-fect exposure. Great photo.', '2003-02-05 18:20:33.000000', NULL, 1),
(208958, 11948, 6451, '<td valign="top">Good picture. I really like the colors and the black background makes the photo very elegant looking. Nice job.</td>', 'Good picture. I really like the colors and the black background makes the photo very elegant looking. Nice job.', '2003-02-05 18:21:12.000000', NULL, 1),
(208959, 11714, 4494, '<td valign="top">Love those cute kittens.  The surrondings are very nice as well.  You get the highest cat picture so far... 8.</td>', 'Love those cute kittens.  The surrondings are very nice as well.  You get the highest cat picture so far... 8.', '2003-02-05 18:21:32.000000', NULL, 1),
(208960, 11721, 6451, '<td valign="top">This picture is very cute.  I like how the dog is wearing the birthday hat and there is cake in his bowl.  It seems to be very well planned out and the picture turned out great.</td>', 'This picture is very cute.  I like how the dog is wearing the birthday hat and there is cake in his bowl.  It seems to be very well planned out and the picture turned out great.', '2003-02-05 18:22:24.000000', NULL, 1),
