INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(209807, 11821, 1280, '<td valign="top">Good job!</td>', 'Good job!', '2003-02-06 16:35:28.000000', NULL, 1),
(209808, 12047, 2752, '<td valign="top">He looks like he was left behind...the sad face and grayscale work well.  The look in eyes is very haunting.  Well done.</td>', 'He looks like he was left behind...the sad face and grayscale work well.  The look in eyes is very haunting.  Well done.', '2003-02-06 16:42:13.000000', NULL, 1),
(209809, 11890, 6593, '<td valign="top">Nice composition and color - definitely 10!</td>', 'Nice composition and color - definitely 10!', '2003-02-06 16:44:04.000000', NULL, 1),
(209811, 11903, 2752, '<td valign="top">Great shot...actually looks like he/she is contemplating how to fix the world problems...Colors a great and the contrast between fur and the fireplace complete the appeal.  Well done.</td>', 'Great shot...actually looks like he/she is contemplating how to fix the world problems...Colors a great and the contrast between fur and the fireplace complete the appeal.  Well done.', '2003-02-06 16:46:09.000000', NULL, 1),
(209812, 12002, 6593, '<td valign="top">Great color, composition, texture and reflection. I like the reflection very much! Good job - definitely 10.</td>', 'Great color, composition, texture and reflection. I like the reflection very much! Good job - definitely 10.', '2003-02-06 16:48:17.000000', NULL, 1),
(209815, 11715, 2752, '<td valign="top">Shows great affection between horse and owner..composition is well done with the play of white and black colors and the vertical bars on the stall doors.  Very nice.</td>', 'Shows great affection between horse and owner..composition is well done with the play of white and black colors and the vertical bars on the stall doors.  Very nice.', '2003-02-06 16:49:30.000000', NULL, 1),
(209816, 11858, 6593, '<td valign="top">Good color but not enough detail.</td>', 'Good color but not enough detail.', '2003-02-06 16:49:54.000000', NULL, 1),
(209817, 12019, 2752, '<td valign="top">crisp and clear...well composed and even though the background is black there is depth showing..wlll done.</td>', 'crisp and clear...well composed and even though the background is black there is depth showing..wlll done.', '2003-02-06 16:52:26.000000', NULL, 1),
(209820, 11705, 2752, '<td valign="top">A very blissful piece..the softness of the blanket and the curves of the folds just adds to the compsition..I like the extended paw .  It even looks totally relaxed.</td>', 'A very blissful piece..the softness of the blanket and the curves of the folds just adds to the compsition..I like the extended paw .  It even looks totally relaxed.', '2003-02-06 16:57:20.000000', NULL, 1),
(209822, 12046, 1280, '<td valign="top">Nice</td>', 'Nice', '2003-02-06 16:58:00.000000', NULL, 1),
(209824, 11866, 2752, '<td valign="top">This "friend" looks very distressed..what with the short lease and horrible collar.<br/>If that was your purpose for this picture you succeeded very well</td>', 'This "friend" looks very distressed..what with the short lease and horrible collar.If that was your purpose for this picture you succeeded very well', '2003-02-06 17:00:42.000000', NULL, 1),
(209825, 11759, 3569, '<td valign="top">Their geese!!!</td>', 'Their geese!!!', '2003-02-06 17:03:19.000000', NULL, 1),
(209829, 11759, 1280, '<td valign="top">Nice pic...mighty Canada Geese would be a more appropriate name though, since that''s what they are.</td>', 'Nice pic...mighty Canada Geese would be a more appropriate name though, since that''s what they are.', '2003-02-06 17:04:09.000000', NULL, 1),
(209830, 11758, 3569, '<td valign="top">Focus looks a bit off.  the green stem in foreground front is very distracting.</td>', 'Focus looks a bit off.  the green stem in foreground front is very distracting.', '2003-02-06 17:04:22.000000', NULL, 1),
(209831, 11923, 3569, '<td valign="top">Nice flower, the frame doesn''t work for me..</td>', 'Nice flower, the frame doesn''t work for me..', '2003-02-06 17:06:02.000000', NULL, 1),
(209833, 11916, 1280, '<td valign="top">Nice...I like the look in his eye, and the grey barn.</td>', 'Nice...I like the look in his eye, and the grey barn.', '2003-02-06 17:08:58.000000', NULL, 1),
(209834, 11781, 3569, '<td valign="top">Beuatiful colors and nice and crisp.  My eye is drawn off the subject by the green bud on the left, to me this is distracting.</td>', 'Beuatiful colors and nice and crisp.  My eye is drawn off the subject by the green bud on the left, to me this is distracting.', '2003-02-06 17:13:45.000000', NULL, 1),
(209838, 11806, 3569, '<td valign="top">Nice flower, but the white background doesn''t do much for me..</td>', 'Nice flower, but the white background doesn''t do much for me..', '2003-02-06 17:20:12.000000', NULL, 1),
(209840, 11908, 3569, '<td valign="top">Beautiful colors and nice sharpness on subject flower.  I would have cropped it to just above the top right flower.  The bud is somewhat distracting in background left.</td>', 'Beautiful colors and nice sharpness on subject flower.  I would have cropped it to just above the top right flower.  The bud is somewhat distracting in background left.', '2003-02-06 17:23:19.000000', NULL, 1),
(209842, 11753, 3569, '<td valign="top">I had several out takes similar to yours.. Good job..</td>', 'I had several out takes similar to yours.. Good job..', '2003-02-06 17:24:18.000000', NULL, 1),
(209844, 11988, 3569, '<td valign="top">I like all but the distracting green under the vase.</td>', 'I like all but the distracting green under the vase.', '2003-02-06 17:25:49.000000', NULL, 1),
(209847, 11957, 3569, '<td valign="top">On of the best this week, Good job...</td>', 'On of the best this week, Good job...', '2003-02-06 17:28:43.000000', NULL, 1),
(209850, 11797, 3569, '<td valign="top">Great colors, but it needs something in the foreground or back ground to add demension..</td>', 'Great colors, but it needs something in the foreground or back ground to add demension..', '2003-02-06 17:34:20.000000', NULL, 1),
(209861, 11769, 2716, '<td valign="top">Very nice sharpness.  Good choice with the black background.  It really brings out the colours.  Good job.</td>', 'Very nice sharpness.  Good choice with the black background.  It really brings out the colours.  Good job.', '2003-02-06 18:02:03.000000', NULL, 1),
(209863, 11921, 2716, '<td valign="top">Double cliche.  A cat and a negative image.  Very smart.  Nice shot.</td>', 'Double cliche.  A cat and a negative image.  Very smart.  Nice shot.', '2003-02-06 18:02:36.000000', NULL, 1),
(209864, 11752, 2716, '<td valign="top">lol  Looks like a little skin head (just kidding).  Great portrait.  Hang it on your wall.  Jacko.  8</td>', 'lol  Looks like a little skin head (just kidding).  Great portrait.  Hang it on your wall.  Jacko.  8', '2003-02-06 18:05:45.000000', NULL, 1),
(209865, 11927, 2716, '<td valign="top">I love it.  Looks like he is taking a nap after having torn the ball to bits and pieces.  Good job.  good luck.  Jacko.  9</td>', 'I love it.  Looks like he is taking a nap after having torn the ball to bits and pieces.  Good job.  good luck.  Jacko.  9', '2003-02-06 18:06:53.000000', NULL, 1),
(209868, 11944, 2716, '<td valign="top">What a great shot.   Needs a bit more focus, but you should hang this puppy on your wall.  9</td>', 'What a great shot.   Needs a bit more focus, but you should hang this puppy on your wall.  9', '2003-02-06 18:09:50.000000', NULL, 1),
(209869, 11785, 2716, '<td valign="top">nice tones.  love the exposure of the sky ...  perfect.  Good luck.  9  jacko.</td>', 'nice tones.  love the exposure of the sky ...  perfect.  Good luck.  9  jacko.', '2003-02-06 18:14:12.000000', NULL, 1),
(209871, 11762, 2716, '<td valign="top">Very, very cute birds.  The hands are distracting, but I still like the shot because the colors are so bright.  Good job.  Jakco.</td>', 'Very, very cute birds.  The hands are distracting, but I still like the shot because the colors are so bright.  Good job.  Jakco.', '2003-02-06 18:16:38.000000', NULL, 1),
(209872, 11835, 772, '<td valign="top">The color in this shot is excellent.. the shallow depth of fiels works very well here... great shot :) - setzler</td>', 'The color in this shot is excellent.. the shallow depth of fiels works very well here... great shot :) - setzler', '2003-02-06 18:16:49.000000', NULL, 1),
(209873, 11925, 2716, '<td valign="top">lol.  That is so cute.  Can he actually see what''s going on?  Good capture.</td>', 'lol.  That is so cute.  Can he actually see what''s going on?  Good capture.', '2003-02-06 18:17:52.000000', NULL, 1),
(209874, 11784, 2716, '<td valign="top">I just love this shot.  The focus is pretty bad, but guess what?  This is one of my favourite shots this week.  It is just too funny.  I just love the look on his face ... looks like he''s wearing glasses or something.  Thanks for the chuckles.  Jacko.  10</td>', 'I just love this shot.  The focus is pretty bad, but guess what?  This is one of my favourite shots this week.  It is just too funny.  I just love the look on his face ... looks like he''s wearing glasses or something.  Thanks for the chuckles.  Jacko.  10', '2003-02-06 18:20:33.000000', NULL, 1),
(209876, 11706, 2716, '<td valign="top">What a cute dog.  Good job.  One recommendatiion ... try moving him away from wall when using your flash ... avoid distracting shadows.  Still a really nice shot.  Jacko.  8</td>', 'What a cute dog.  Good job.  One recommendatiion ... try moving him away from wall when using your flash ... avoid distracting shadows.  Still a really nice shot.  Jacko.  8', '2003-02-06 18:24:19.000000', NULL, 1),
(209877, 11932, 2716, '<td valign="top">Wonderfull shot.  I love silhouettes and this one is fantastic.  Excellent composition.  Good luck.  Jacko  9</td>', 'Wonderfull shot.  I love silhouettes and this one is fantastic.  Excellent composition.  Good luck.  Jacko  9', '2003-02-06 18:25:37.000000', NULL, 1),
(209879, 11937, 2716, '<td valign="top">lol good shot.  Couldn''t figure out from the thumbail.  Cute set up and great idea.  Jacko.</td>', 'lol good shot.  Couldn''t figure out from the thumbail.  Cute set up and great idea.  Jacko.', '2003-02-06 18:27:10.000000', NULL, 1),
(209880, 11677, 2716, '<td valign="top">How on earth did you get that border (I hope you give us the details)?  This picture is so cute ... trying to be like mom and dad?  Great capture.  jacko  8.</td>', 'How on earth did you get that border (I hope you give us the details)?  This picture is so cute ... trying to be like mom and dad?  Great capture.  jacko  8.', '2003-02-06 18:28:55.000000', NULL, 1),
(209881, 12032, 2716, '<td valign="top">It''s a cliche, but it''s a nice one.  The colour of the sky makes this shot.  Good luck.</td>', 'It''s a cliche, but it''s a nice one.  The colour of the sky makes this shot.  Good luck.', '2003-02-06 18:29:24.000000', NULL, 1),
(209882, 11962, 2716, '<td valign="top">Nice sujbect.  Would need a bit more focus and I''d like to see the subject dead centre (rule of thirds doesn''t always work).  Jacko.  6</td>', 'Nice sujbect.  Would need a bit more focus and I''d like to see the subject dead centre (rule of thirds doesn''t always work).  Jacko.  6', '2003-02-06 18:30:20.000000', NULL, 1),
(209883, 11855, 2716, '<td valign="top">Very simple and very nice.  Nice choice of background for the subejct.  Jacko.  8</td>', 'Very simple and very nice.  Nice choice of background for the subejct.  Jacko.  8', '2003-02-06 18:30:44.000000', NULL, 1),
(209884, 11705, 2716, '<td valign="top">Great capture.  I love cats and I really like this picture.  Has a real peaceful fee to it.  Maybe crop out a bit of the top ... little too busy.  Still a very nice shot.  Jacko.  8</td>', 'Great capture.  I love cats and I really like this picture.  Has a real peaceful fee to it.  Maybe crop out a bit of the top ... little too busy.  Still a very nice shot.  Jacko.  8', '2003-02-06 18:31:32.000000', NULL, 1),
(209885, 11950, 2716, '<td valign="top">lol.  that is so cute.  I love the composition you used ... really highlights the camera.  The cowboy hat makes it interesting too.  Good job. 8</td>', 'lol.  that is so cute.  I love the composition you used ... really highlights the camera.  The cowboy hat makes it interesting too.  Good job. 8', '2003-02-06 18:32:36.000000', NULL, 1),
(209887, 11717, 2716, '<td valign="top">lol  that is funny.  I don''t quite understand the picture but it''s still funny.  Jacko.  7</td>', 'lol  that is funny.  I don''t quite understand the picture but it''s still funny.  Jacko.  7', '2003-02-06 18:33:28.000000', NULL, 1),
(209888, 11829, 2716, '<td valign="top">Nice capture.  Iike the crop you used (panoramic).  Jacko.</td>', 'Nice capture.  Iike the crop you used (panoramic).  Jacko.', '2003-02-06 18:34:01.000000', NULL, 1),
(209889, 11739, 2716, '<td valign="top">This is interesting.  The plane trails make this shot.  Good eye.  Look like the planes are flying into the sun.</td>', 'This is interesting.  The plane trails make this shot.  Good eye.  Look like the planes are flying into the sun.', '2003-02-06 18:34:38.000000', NULL, 1),
(209890, 11847, 2716, '<td valign="top">The texture on this one is so odd and interesting. .  Is that natural or did you apply a blurring filte?.  The tongue makes this picture so cute.</td>', 'The texture on this one is so odd and interesting. .  Is that natural or did you apply a blurring filte?.  The tongue makes this picture so cute.', '2003-02-06 18:35:49.000000', NULL, 1),
