INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(210089, 11937, 4648, '<td valign="top">To be a drop shouldn''t you have turned it upside down.  This is .............of a unique and different mind.  Lots of imagination.  Disn''t erase your fingerprints though.  Let''s see if we can figure out who you are from the prints.  You get a 10 just for such a different idea, forget that the photo is very well done.  Don''t even mind the dark place on the right side.  Didn''t even see it until I was already commenting.  That''s how much the rest of it, the drop, had my attention.  I bet you are in the top 10.  Way to go.  Great photo and fantastic subject.</td>', 'To be a drop shouldn''t you have turned it upside down.  This is .............of a unique and different mind.  Lots of imagination.  Disn''t erase your fingerprints though.  Let''s see if we can figure out who you are from the prints.  You get a 10 just for such a different idea, forget that the photo is very well done.  Don''t even mind the dark place on the right side.  Didn''t even see it until I was already commenting.  That''s how much the rest of it, the drop, had my attention.  I bet you are in the top 10.  Way to go.  Great photo and fantastic subject.', '2003-02-06 23:36:31.000000', NULL, 1),
(210090, 11897, 5268, '<td valign="top">Nice colors and focus. Good job!! Cub</td>', 'Nice colors and focus. Good job!! Cub', '2003-02-06 23:36:57.000000', NULL, 1),
(210091, 11903, 5268, '<td valign="top">Beautful dog. Nice colors, and composition.. Cub</td>', 'Beautful dog. Nice colors, and composition.. Cub', '2003-02-06 23:38:23.000000', NULL, 1),
(210093, 11754, 5268, '<td valign="top">Great colors and composition. The focus is a little soft but looks good. Cub</td>', 'Great colors and composition. The focus is a little soft but looks good. Cub', '2003-02-06 23:41:31.000000', NULL, 1),
(210094, 11951, 4648, '<td valign="top">Are you using an unusual lens.  The cityscape appear to be rounded and all leaning toward the center.  The sky and clouds are beautiful, but the bottom 1/10 of the photo ruins the sky.  Flatten out the horizon and you have a winner.</td>', 'Are you using an unusual lens.  The cityscape appear to be rounded and all leaning toward the center.  The sky and clouds are beautiful, but the bottom 1/10 of the photo ruins the sky.  Flatten out the horizon and you have a winner.', '2003-02-06 23:41:51.000000', NULL, 1),
(210095, 11929, 5268, '<td valign="top">Beautiful shot. Nice colors, focus and composition.  Great!! Cub</td>', 'Beautiful shot. Nice colors, focus and composition.  Great!! Cub', '2003-02-06 23:44:14.000000', NULL, 1),
