INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(211889, 11865, 472, '<td valign="top">lol. somehow, in the inner recesses of my mind, i knew this would win .. people are such suckers for water drop shots, and this one is so cool with the checkers :) .. great job!</td>', 'lol. somehow, in the inner recesses of my mind, i knew this would win .. people are such suckers for water drop shots, and this one is so cool with the checkers :) .. great job!', '2003-02-10 07:42:23.000000', NULL, 0),
(211894, 11963, 3599, '<td valign="top">Greetings from the Critique Club.<br/> <br/>This is a well composed and framed shot.  I fortunately have a dog that sits still for photos but I imagine it can be a headache.  I would to have liked to see more of his face.  The hair in the way takes away from the photo.  I disagree with the comment of wasting B&amp;W on this photo.  B&amp;W was a good choice as I''m sure color would have been too.  I think you have good DOF and choose a good crop.  Maybe a little less neck as it a little soft though.  All in all this a good photo.  Keep up the good work.  Best of luck in future challenges.</td>', 'Greetings from the Critique Club. This is a well composed and framed shot.  I fortunately have a dog that sits still for photos but I imagine it can be a headache.  I would to have liked to see more of his face.  The hair in the way takes away from the photo.  I disagree with the comment of wasting B&W on this photo.  B&W was a good choice as I''m sure color would have been too.  I think you have good DOF and choose a good crop.  Maybe a little less neck as it a little soft though.  All in all this a good photo.  Keep up the good work.  Best of luck in future challenges.', '2003-02-10 07:51:37.000000', NULL, 0),
(211900, 11803, 472, '<td valign="top">this is the best baby in here :) .. nice use of wide angle</td>', 'this is the best baby in here :) .. nice use of wide angle', '2003-02-10 08:04:16.000000', NULL, 0),
